functions._lrGetAllRules:
function _lrGetAllRules() {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.getAll !== "function") {
    return Promise.resolve([]);
  }
  return window.eli.storage.getAll(STORE_RISK_RULES_LR).then(function (rows) {
    return (rows || []).filter(function (r) {
      return r && typeof r === "object" && (!r.id || String(r.id).charAt(0) !== "_");
    });
  }).catch(function () { return []; });
}

functions._lrPutRule:
function _lrPutRule(rule) {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.put !== "function") {
    return Promise.resolve();
  }
  return window.eli.storage.put(STORE_RISK_RULES_LR, rule).catch(function () {});
}

functions._lrDeleteRule:
function _lrDeleteRule(id) {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.delete !== "function") {
    return Promise.resolve();
  }
  return window.eli.storage.delete(STORE_RISK_RULES_LR, id).catch(function () {});
}

functions._lrToast:
function _lrToast(msg, kind) {
  if (typeof window.showToast === "function") window.showToast(msg, kind || "info");
}

// FROM v2 showRiskRulesManager — main UI. Lists every rule with edit /
// delete / toggle controls; top toolbar offers upload, export, wipe-all.
// Renders into #output via eli.ui.claimOutput.

functions.lrShowRiskRulesManager:
function lrShowRiskRulesManager() {
  var out = (window.eli && window.eli.ui && window.eli.ui.claimOutput)
    ? window.eli.ui.claimOutput()
    : document.getElementById("output");
  if (!out) return;
  out.classList.add("eli-view-enter");
  var header = (typeof window.createConfigHeader === "function")
    ? window.createConfigHeader("CONFIGURATION", "⚙️", "Risk Rules Engine")
    : (function () { var d = document.createElement("div"); d.textContent = "Risk Rules Engine"; return d; })();
  out.appendChild(header);

  var toolbar = document.createElement("div");
  toolbar.style.cssText = "padding:0 15px 15px 15px; display:flex; gap:10px;";
  var btn = function (label, opts) {
    return (typeof window.eliButton === "function")
      ? window.eliButton(label, opts || {})
      : '<button id="' + (opts && opts.id || "") + '" class="btn-action">' + label + "</button>";
  };
  toolbar.innerHTML =
    btn("UPLOAD JSON", { id: "lrBtnUploadRules", icon: "📂", style: "flex:1; font-size:10px;" }) +
    btn("EXPORT JSON", { id: "lrBtnExportRules", icon: "⬇️", style: "flex:1; font-size:10px;" }) +
    btn("DELETE ALL", { id: "lrBtnDeleteAllRules", icon: "🗑️", danger: true, style: "flex:1; font-size:10px;" }) +
    '<input type="file" id="lrFileRuleUpload" accept=".json" style="display:none;">';
  out.appendChild(toolbar);

  var listContainer = document.createElement("div");
  listContainer.id = "lrRulesListContainer";
  listContainer.style.cssText = "padding:0 15px; overflow-y:auto; max-height:calc(100vh - 180px);";
  out.appendChild(listContainer);

  var addBtnWrap = document.createElement("div");
  addBtnWrap.style.cssText = "padding:0 15px;";
  addBtnWrap.innerHTML = btn("ADD NEW RULE", {
    id: "lrBtnAddNewRule",
    primary: true,
    icon: "➕",
    style: "width:100%; padding:12px; font-weight:800;",
  });
  out.appendChild(addBtnWrap);
  addBtnWrap.querySelector("#lrBtnAddNewRule").onclick = function () { lrShowRuleEditor(null); };

  _lrGetAllRules().then(function (rules) {
    if (rules.length === 0) {
      // Seed default AI rule when DB is empty (v2 parity).
      var seed = {
        id: "rule_ai_protection",
        type: "LLM and Artificial Intelligence",
        check:
          "Ensure Supplier MUST disclose AI usage. Verify Supplier is PROHIBITED from using Colgate Data to train their models. Confirm Colgate owns all AI outputs.",
        clause: "(a) “AI Technologies” means deep learning, machine learning, and other artificial intelligence technologies. Prior to making use of any AI Technologies in providing the Deliverables or performing the Services (except for incidental use), Supplier shall disclose in writing to Company a description of the AI Technologies to be used and the purpose for using them.\n\n(b) Supplier shall not use Company Confidential Information to train, test or verify (“Train”) any AI models, unless (i) such Training is approved by Company in writing or (ii) the AI model is specifically developed for Company’s exclusive use. All Company inputs, and all outputs that constitute Deliverables generated by the AI Technologies, constitute Company’s Confidential Information hereunder. Supplier agrees that Company owns any such outputs and/or models generated by or through the use of Company Confidential Information.\n\n(c) Supplier warrants that (i) Supplier AI Technologies were developed and trained in compliance with all applicable laws; (ii) Supplier’s use of AI Technologies shall comply with all applicable laws; and (iii) Supplier shall not commingle information about Company’s strategies with that of any third party to facilitate collusive behavior.",
        agreementTypes: ["all"],
        enabled: true,
      };
      rules = [seed];
      _lrPutRule(seed);
    }
    lrRenderRulesList(rules);
  });

  document.getElementById("lrBtnDeleteAllRules").onclick = function () {
    if (typeof window.showEliDialog !== "function") return;
    var overlay = window.showEliDialog({
      variant: "danger",
      icon: "🗑️",
      title: "Delete All Rules?",
      body: "This will wipe the entire rule database.<br><br>(The system will re-seed the default AI rule upon reload.)",
      buttons: [
        { id: "lrBtnConfDelAll", label: "Yes, Delete", cls: "btn-action", style: "flex:1; background:#c62828; color:white; border:none; font-weight:bold;" },
        { id: "lrBtnCancelDelAll", label: "Cancel", style: "flex:1;", onclick: function () { overlay.remove(); } },
      ],
    });
    document.getElementById("lrBtnConfDelAll").onclick = function () {
      _lrGetAllRules().then(function (rules) {
        return Promise.all(rules.map(function (r) { return _lrDeleteRule(r.id); }));
      }).then(function () {
        overlay.remove();
        _lrToast("🗑️ All Rules Deleted. Reloading…");
        setTimeout(function () { lrShowRiskRulesManager(); }, 600);
      });
    };
  };

  document.getElementById("lrBtnUploadRules").onclick = function () {
    document.getElementById("lrFileRuleUpload").click();
  };
  document.getElementById("lrFileRuleUpload").onchange = function (e) {
    var file = e.target.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function (evt) {
      try {
        var json = JSON.parse(evt.target.result);
        if (!Array.isArray(json)) { _lrToast("❌ Invalid JSON format", "err"); return; }
        _lrGetAllRules().then(function (current) {
          var combined = (current || []).concat(json);
          var seen = {};
          var unique = [];
          combined.forEach(function (r) {
            if (!r) return;
            if (!r.id) r.id = "rule_" + Date.now() + "_" + Math.floor(Math.random() * 1e6);
            if (!seen[r.id]) { seen[r.id] = true; unique.push(r); }
          });
          Promise.all(unique.map(_lrPutRule)).then(function () {
            _lrToast("✅ Loaded " + json.length + " rules.", "ok");
            lrRenderRulesList(unique);
          });
        });
      } catch (err) { _lrToast("❌ Error parsing JSON", "err"); }
    };
    reader.readAsText(file);
  };

  document.getElementById("lrBtnExportRules").onclick = function () {
    _lrGetAllRules().then(function (rules) {
      var jsonStr = JSON.stringify(rules, null, 2);
      var overlay = document.createElement("div");
      overlay.className = "eli-overlay";
      overlay.style.zIndex = "99999";
      var box = document.createElement("div");
      box.className = "tool-box slide-in";
      box.style.cssText = "background:white; width:450px; max-width:90%; padding:0; border-radius:0; border:1px solid #1565c0; box-shadow:0 20px 50px rgba(0,0,0,0.3); display:flex; flex-direction:column;";
      var headerHtml = (typeof window.createConfigHeader === "function")
        ? window.createConfigHeader(null, null, "EXPORT RULES <button id='lrBtnCloseExport' style='float:right; border:none; background:none; cursor:pointer; color:inherit; font-weight:bold;'>✕</button>").outerHTML
        : "<div style='padding:10px;font-weight:700;'>Export Rules <button id='lrBtnCloseExport'>✕</button></div>";
      box.innerHTML = headerHtml +
        '<div style="padding:15px; background:#f0f7ff; border-bottom:1px solid #bbdefb;">' +
          '<div style="font-size:11px; color:#546e7a;">Copy the JSON below to back up your risk rules.</div>' +
        '</div>' +
        '<textarea id="lrExportArea" style="width:100%; height:250px; border:none; background:#fafafa; padding:10px; font-family:monospace; font-size:10px; resize:none; box-sizing:border-box; outline:none; color:#333;">' + jsonStr + '</textarea>' +
        '<div style="padding:15px; display:flex; gap:10px; background:#fff; border-top:1px solid #e0e0e0;">' +
          (typeof window.eliButton === "function"
            ? window.eliButton("COPY TO CLIPBOARD", { id: "lrBtnCopyExport", primary: true, icon: "📄", style: "flex:2; padding:12px; font-weight:800; font-size:12px;" })
            : '<button id="lrBtnCopyExport" class="btn-action">📄 COPY</button>') +
          '<button id="lrBtnDownloadFile" class="btn-action" style="flex:1; background:#f5f5f5; color:#333; border:1px solid #ccc;">⬇️ Download</button>' +
        '</div>';
      overlay.appendChild(box);
      document.body.appendChild(overlay);
      document.getElementById("lrBtnCloseExport").onclick = function () { overlay.remove(); };
      document.getElementById("lrBtnCopyExport").onclick = function () {
        var txt = document.getElementById("lrExportArea");
        txt.select();
        navigator.clipboard.writeText(txt.value).then(function () {
          var b = document.getElementById("lrBtnCopyExport");
          if (!b) return;
          b.innerText = "✅ COPIED!";
          b.style.background = "#2e7d32";
          setTimeout(function () {
            b.innerText = "📄 COPY TO CLIPBOARD";
            b.style.background = "#1565c0";
          }, 2000);
        });
      };
      document.getElementById("lrBtnDownloadFile").onclick = function () {
        var blob = new Blob([jsonStr], { type: "application/json" });
        var url = URL.createObjectURL(blob);
        var a = document.createElement("a");
        a.href = url;
        a.download = "Colgate_Risk_Rules.json";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        _lrToast("⬇️ Download Started");
      };
    });
  };
}

// FROM v2 renderRulesList — one card per rule: agreement type, check
// description, toggle (enabled), edit, delete. Click edit → opens
// lrShowRuleEditor. Click delete → confirms then removes.

functions.lrRenderRulesList:
function lrRenderRulesList(rules) {
  var container = document.getElementById("lrRulesListContainer");
  if (!container) return;
  container.innerHTML = "";
  rules.forEach(function (r) {
    var isEnabled = r.enabled !== false;
    var card = document.createElement("div");
    card.className = "tool-box slide-in";
    var accentColor = isEnabled ? "#7b1fa2" : "#cbd5e1";
    card.style.cssText =
      "background:white; border:1px solid #ddd; border-left:4px solid " + accentColor +
      "; padding:12px; margin-bottom:10px; border-radius:0; position:relative;" +
      (isEnabled ? "" : " opacity:0.6;");
    var typeDisplay = r.type || "";
    if (Array.isArray(r.agreementTypes) && r.agreementTypes.length > 0) {
      typeDisplay = r.agreementTypes.join(", ");
    }
    var statusBadge = (typeof window.eliBadge === "function")
      ? window.eliBadge(isEnabled ? "ON" : "OFF", isEnabled ? "success" : "default")
      : (isEnabled ? '<span style="color:#16a34a;font-weight:700;">ON</span>' : '<span style="color:#94a3b8;">OFF</span>');
    var sectionLbl = function (txt, color) {
      return (typeof window.eliSectionLabel === "function")
        ? window.eliSectionLabel(txt, { color: color })
        : '<div style="font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:0.6px;color:' + (color || "#475569") + ';margin-bottom:4px;">' + txt + '</div>';
    };
    card.innerHTML =
      '<div style="position:absolute; top:8px; right:8px; display:flex; gap:5px; align-items:center;">' +
      '<label style="cursor:pointer; display:flex; align-items:center; gap:3px;">' +
      '<input type="checkbox" class="lr-chk-rule-toggle" ' + (isEnabled ? "checked" : "") + ' style="cursor:pointer;"> ' +
      statusBadge +
      "</label>" +
      '<button class="lr-btn-edit-rule" style="background:none; border:none; cursor:pointer; font-size:14px;" title="Edit">✏️</button>' +
      '<button class="lr-btn-del-rule" style="background:none; border:none; cursor:pointer; font-size:14px;" title="Delete">🗑️</button>' +
      "</div>" +
      sectionLbl("AGREEMENT TYPE", "#7b1fa2") +
      '<div style="font-size:12px; font-weight:700; color:#333; margin-bottom:8px;">' + typeDisplay + "</div>" +
      sectionLbl("RISK CHECK", "#c62828") +
      '<div style="font-size:11px; color:#555; line-height:1.4;">' + (r.check || "") + "</div>";
    card.querySelector(".lr-chk-rule-toggle").onchange = function () {
      var enabled = this.checked;
      _lrGetAllRules().then(function (allRules) {
        var target = (allRules || []).find(function (x) { return x.id === r.id; });
        if (target) {
          target.enabled = enabled;
          _lrPutRule(target);
        }
      });
    };
    card.querySelector(".lr-btn-edit-rule").onclick = function () { lrShowRuleEditor(r); };
    card.querySelector(".lr-btn-del-rule").onclick = function () {
      if (typeof window.showEliDialog !== "function") return;
      var overlay = window.showEliDialog({
        variant: "danger",
        icon: "🗑️",
        title: "Delete Rule?",
        body: "Are you sure you want to remove this risk rule?",
        buttons: [
          { id: "lrBtnConfDelSingle", label: "Delete", cls: "btn-action", style: "flex:1; background:#c62828; color:white; border:none; font-weight:bold;" },
          { id: "lrBtnCancelDelSingle", label: "Cancel", style: "flex:1;", onclick: function () { overlay.remove(); } },
        ],
      });
      document.getElementById("lrBtnConfDelSingle").onclick = function () {
        _lrDeleteRule(r.id).then(function () {
          overlay.remove();
          _lrToast("🗑️ Rule Deleted");
          _lrGetAllRules().then(lrRenderRulesList);
        });
      };
    };
    container.appendChild(card);
  });
}

// FROM v2 showRuleEditor — overlay editor for one rule. Lists agreement
// types from STORE_AGREEMENT_TYPES (or falls back to a free-text custom
// list), plus check description + suggested clause text.

functions.lrShowRuleEditor:
function lrShowRuleEditor(rule) {
  var isEdit = !!rule;
  var data = rule || { type: "", check: "", clause: "", agreementTypes: [], enabled: true };
  var selectedTypes = (data.agreementTypes && data.agreementTypes.length) ? data.agreementTypes.slice() : (data.type ? [data.type] : []);

  var _getCatalog = function () {
    if (typeof window.getAgreementTypeMatcher === "function") {
      try { return window.getAgreementTypeMatcher() || []; } catch (_) {}
    }
    return [];
  };
  var _agCatalog = _getCatalog();
  var customTypes = selectedTypes.filter(function (t) {
    return !_agCatalog.some(function (c) { return c.label === t; });
  });

  var overlay = document.createElement("div");
  overlay.className = "eli-overlay";
  var box = document.createElement("div");
  box.className = "tool-box slide-in";
  box.style.cssText = "background:white; width:380px; max-height:85vh; padding:20px; border-left:5px solid #7b1fa2; box-shadow:0 10px 30px rgba(0,0,0,0.3); border-radius:0; overflow-y:auto;";

  var esc = function (s) {
    return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  };
  var checkboxesHtml = _agCatalog.map(function (cat) {
    var checked = selectedTypes.indexOf(cat.label) !== -1 ? "checked" : "";
    return '<label style="display:flex; align-items:center; gap:6px; padding:4px 0; cursor:pointer; font-size:12px; font-weight:600; color:#334155;">' +
      '<input type="checkbox" class="lr-chk-agree-type" value="' + esc(cat.label) + '" ' + checked + ' style="cursor:pointer;"> ' +
      esc(cat.label) +
      '</label>';
  }).join("");
  var customHtml = customTypes.map(function (ct) {
    return '<label style="display:flex; align-items:center; gap:6px; padding:4px 0; cursor:pointer; font-size:12px; font-weight:600; color:#7b1fa2;">' +
      '<input type="checkbox" class="lr-chk-agree-type" value="' + esc(ct) + '" checked style="cursor:pointer;"> ' +
      esc(ct) +
      ' <span style="font-size:9px; color:#94a3b8;">(custom)</span></label>';
  }).join("");

  var sectionLbl = (typeof window.eliSectionLabel === "function")
    ? window.eliSectionLabel(isEdit ? "EDIT RULE" : "NEW RULE", { color: "#7b1fa2", fontSize: "12px", marginBottom: "15px" })
    : '<div style="font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:0.6px;color:#7b1fa2;margin-bottom:15px;">' + (isEdit ? "EDIT RULE" : "NEW RULE") + '</div>';

  box.innerHTML =
    sectionLbl +
    '<label class="tool-label">Applies to Agreement Types</label>' +
    '<div id="lrAgreeTypeCheckboxes" style="max-height:180px; overflow-y:auto; border:1px solid #e2e8f0; border-radius:6px; padding:8px 12px; margin-bottom:8px; background:#f8fafc;">' +
      checkboxesHtml + customHtml +
    '</div>' +
    '<div style="margin-bottom:12px;">' +
      '<input type="text" id="lrEditCustomAgreeType" class="tool-input" placeholder="Type a custom agreement type here..." style="width:100%; margin:0 0 6px 0; font-size:13px; padding:10px 12px; height:auto; border:2px solid #e2e8f0; border-radius:6px; box-sizing:border-box;">' +
      '<button id="lrBtnAddCustomType" class="btn-action" style="width:100%; padding:10px 16px; font-size:11px; font-weight:800; background:#7b1fa2; color:white; border-radius:6px; text-transform:uppercase; letter-spacing:0.5px;">+ Add Custom Agreement Type</button>' +
    '</div>' +
    '<label class="tool-label">Risk Check Description</label>' +
    '<textarea id="lrEditRuleCheck" class="tool-input" style="height:60px;">' + esc(data.check) + '</textarea>' +
    '<label class="tool-label">Suggested Clause (Optional)</label>' +
    '<textarea id="lrEditRuleClause" class="tool-input" style="height:60px;">' + esc(data.clause || "") + '</textarea>' +
    '<div style="display:flex; gap:10px; margin-top:10px;">' +
      '<button id="lrBtnSaveRule" class="btn-action" style="flex:1; background:#7b1fa2; color:white; font-weight:bold;">SAVE</button>' +
      '<button id="lrBtnCancelRule" class="btn-action" style="flex:1;">Cancel</button>' +
    '</div>';

  overlay.appendChild(box);
  document.body.appendChild(overlay);

  document.getElementById("lrBtnAddCustomType").onclick = function () {
    var input = document.getElementById("lrEditCustomAgreeType");
    var val = input.value.trim();
    if (!val) return;
    var container = document.getElementById("lrAgreeTypeCheckboxes");
    var lbl = document.createElement("label");
    lbl.style.cssText = "display:flex; align-items:center; gap:6px; padding:4px 0; cursor:pointer; font-size:12px; font-weight:600; color:#7b1fa2;";
    lbl.innerHTML =
      '<input type="checkbox" class="lr-chk-agree-type" value="' + esc(val) + '" checked style="cursor:pointer;"> ' +
      esc(val) +
      ' <span style="font-size:9px; color:#94a3b8;">(custom)</span>';
    container.appendChild(lbl);
    input.value = "";
  };
  document.getElementById("lrBtnCancelRule").onclick = function () { overlay.remove(); };
  document.getElementById("lrBtnSaveRule").onclick = function () {
    var checkboxes = overlay.querySelectorAll(".lr-chk-agree-type:checked");
    var types = [];
    checkboxes.forEach(function (cb) { types.push(cb.value); });
    var newCheck = document.getElementById("lrEditRuleCheck").value;
    var newClause = document.getElementById("lrEditRuleClause").value;
    if (types.length === 0 || !newCheck) {
      _lrToast("⚠️ Select at least one agreement type and add a check description", "warn");
      return;
    }
    _lrGetAllRules().then(function (rules) {
      var list = rules || [];
      var record;
      if (isEdit) {
        var idx = list.findIndex(function (r) { return r.id === data.id; });
        if (idx !== -1) {
          record = Object.assign({}, list[idx], {
            type: types.join(", "),
            agreementTypes: types,
            check: newCheck,
            clause: newClause,
          });
          list[idx] = record;
        }
      } else {
        record = {
          id: "rule_" + Date.now() + "_" + Math.floor(Math.random() * 1e6),
          type: types.join(", "),
          agreementTypes: types,
          check: newCheck,
          clause: newClause,
          enabled: true,
        };
        list.push(record);
      }
      _lrPutRule(record).then(function () {
        overlay.remove();
        _lrToast("✅ Rule Saved", "ok");
        lrRenderRulesList(list);
      });
    });
  };
}

engine.computeWordDiffV2:
function computeWordDiffV2(oldText, newText) {
  if (!oldText) oldText = "";
  if (!newText) newText = "";
  if (typeof Diff === "undefined" || typeof Diff.diffArrays !== "function") {
    return oldText === newText
      ? [{ type: "equal", text: oldText }]
      : [{
          type: "change",
          oldWords: oldText.split(/\s+/).filter(Boolean),
          newWords: newText.split(/\s+/).filter(Boolean),
          id: "hunk_0",
        }];
  }
  var oldTokens = oldText.match(/\S+/g) || [];
  var newTokens = newText.match(/\S+/g) || [];
  var parts = Diff.diffArrays(oldTokens, newTokens);
  var hunks = [];
  var currentHunk = null;
  parts.forEach(function (p) {
    if (!p.added && !p.removed) {
      if (currentHunk) { hunks.push(currentHunk); currentHunk = null; }
      p.value.forEach(function (w) { hunks.push({ type: "equal", text: w }); });
    } else {
      if (!currentHunk) currentHunk = { type: "change", oldWords: [], newWords: [], id: "hunk_" + hunks.length };
      if (p.removed) p.value.forEach(function (w) { currentHunk.oldWords.push(w); });
      if (p.added)   p.value.forEach(function (w) { currentHunk.newWords.push(w); });
    }
  });
  if (currentHunk) hunks.push(currentHunk);
  return hunks;
}

// FROM v2 renderSurgicalRedlineHtml (line 18228) — verbatim except
// class names (v3 uses CSS classes; v2 used inline styles).
// Equal hunks are single tokens (`text` field) joined by " ".
// Change hunks render as one .surgical-hunk span with strike-through
// old + bold green new; data-hunk-id indexes click-to-apply.

engine.renderSurgicalRedlineHtml:
function renderSurgicalRedlineHtml(hunks) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  if (!Array.isArray(hunks)) return "";
  var html = "";
  var changeIndex = 0;
  hunks.forEach(function (h) {
    if (!h) return;
    if (h.type === "equal") {
      html += _esc(h.text || "") + " ";
      return;
    }
    var oldText = (h.oldWords || []).join(" ");
    var newText = (h.newWords || []).join(" ");
    html +=
      '<span class="surgical-hunk" data-hunk-id="' + changeIndex +
      '" title="Click to apply this change">';
    if (oldText) {
      html += '<span class="surgical-hunk-del">' + _esc(oldText) + '</span> ';
    }
    if (newText) {
      html += '<span class="surgical-hunk-ins">' + _esc(newText) + '</span> ';
    }
    html += "</span>";
    changeIndex++;
  });
  return html.trim();
}

// Filter risk rules to those that apply to the current agreement type.
// FROM v2 runDeal360Analysis lines 43-74. Rules with "all" in their
// agreementTypes array are always included; others are matched by
// loose alias compare. Loose match catches "MSA" vs "Master Services
// Agreement" etc.

engine.filterRulesByType:
function filterRulesByType(allRules, docType) {
  if (!Array.isArray(allRules)) return [];
  var detected = String(docType || "").toLowerCase();
  return allRules.filter(function (r) {
    if (!r || r.enabled === false) return false;
